// ─── Users ───────────────────────────────────────────────────────────────────

export interface User {
  id: string;
  name: string;
  email: string;
  createdAt: string;
  updatedAt: string;
}

export interface CreateUserBody {
  name: string;
  email: string;
}

export interface UpdateUserBody {
  name?: string;
  email?: string;
}

// ─── Projects ────────────────────────────────────────────────────────────────

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
  createdAt: string;
  updatedAt: string;
}

export interface CreateProjectBody {
  name: string;
  description?: string;
}

export interface UpdateProjectBody {
  name?: string;
  description?: string;
}

export interface AddMemberBody {
  userId: string;
}

// ─── Tasks ───────────────────────────────────────────────────────────────────

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export const VALID_TRANSITIONS: Record<TaskStatus, TaskStatus[]> = {
  todo: ['in-progress'],
  'in-progress': ['done'],
  done: [],
};

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  projectId: string;
  assigneeId: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface CreateTaskBody {
  title: string;
  description?: string;
  projectId: string;
  assigneeId?: string;
}

export interface UpdateTaskBody {
  title?: string;
  description?: string;
}

export interface UpdateTaskStatusBody {
  status: TaskStatus;
}

export interface AssignTaskBody {
  assigneeId: string | null;
}

// ─── Comments ────────────────────────────────────────────────────────────────

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string;
}

export interface CreateCommentBody {
  taskId: string;
  authorId: string;
  body: string;
}

// ─── Notifications ────────────────────────────────────────────────────────────

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string;
}

// ─── HTTP Helpers ─────────────────────────────────────────────────────────────

export interface ParsedRequest {
  method: string;
  pathname: string;
  segments: string[];
  query: Record<string, string>;
  body: unknown;
}

export interface RouteContext {
  req: ParsedRequest;
  params: Record<string, string>;
}

export type RouteHandler = (ctx: RouteContext) => RouteResponse | Promise<RouteResponse>;

export interface RouteResponse {
  status: number;
  body: unknown;
}

import { randomUUID } from 'crypto';
import type { User, Project, Task, Comment, Notification } from './types.js';

// ─── In-Memory Collections ────────────────────────────────────────────────────

export const users = new Map<string, User>();
export const projects = new Map<string, Project>();
export const tasks = new Map<string, Task>();
export const comments = new Map<string, Comment>();
export const notifications = new Map<string, Notification>();

// ─── ID Generation ───────────────────────────────────────────────────────────

export function newId(): string {
  return randomUUID();
}

// ─── Timestamp Helper ────────────────────────────────────────────────────────

export function now(): string {
  return new Date().toISOString();
}

// ─── Notification Factory ────────────────────────────────────────────────────

export function createNotification(userId: string, message: string): Notification {
  const notification: Notification = {
    id: newId(),
    userId,
    message,
    read: false,
    createdAt: now(),
  };
  notifications.set(notification.id, notification);
  return notification;
}

import type { RouteResponse } from './types.js';

// ─── Standard Response Builders ───────────────────────────────────────────────

export function ok(body: unknown): RouteResponse {
  return { status: 200, body };
}

export function created(body: unknown): RouteResponse {
  return { status: 201, body };
}

export function noContent(): RouteResponse {
  return { status: 204, body: null };
}

export function badRequest(message: string): RouteResponse {
  return { status: 400, body: { error: message } };
}

export function notFound(message = 'Not found'): RouteResponse {
  return { status: 404, body: { error: message } };
}

export function conflict(message: string): RouteResponse {
  return { status: 409, body: { error: message } };
}

export function unprocessable(message: string): RouteResponse {
  return { status: 422, body: { error: message } };
}

export function methodNotAllowed(): RouteResponse {
  return { status: 405, body: { error: 'Method not allowed' } };
}

// ─── Validation Helpers ───────────────────────────────────────────────────────

export function isString(value: unknown): value is string {
  return typeof value === 'string';
}

export function isNonEmptyString(value: unknown): value is string {
  return typeof value === 'string' && value.trim().length > 0;
}

export function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

import * as store from '../store.js';
import {
  ok, created, noContent,
  badRequest, notFound, conflict,
  isNonEmptyString, isObject,
} from '../helpers.js';
import type { RouteContext, RouteResponse, CreateUserBody, UpdateUserBody } from '../types.js';

// ─── GET /users ───────────────────────────────────────────────────────────────

export function listUsers(_ctx: RouteContext): RouteResponse {
  return ok(Array.from(store.users.values()));
}

// ─── POST /users ──────────────────────────────────────────────────────────────

export function createUser(ctx: RouteContext): RouteResponse {
  const body = ctx.req.body;

  if (!isObject(body)) return badRequest('Request body must be a JSON object');

  const { name, email } = body as CreateUserBody;

  if (!isNonEmptyString(name)) return badRequest('Field "name" is required and must be a non-empty string');
  if (!isNonEmptyString(email)) return badRequest('Field "email" is required and must be a non-empty string');

  // Enforce unique email
  for (const u of store.users.values()) {
    if (u.email === email) return conflict(`A user with email "${email}" already exists`);
  }

  const user = {
    id: store.newId(),
    name: name.trim(),
    email: email.trim(),
    createdAt: store.now(),
    updatedAt: store.now(),
  };

  store.users.set(user.id, user);
  return created(user);
}

// ─── GET /users/:id ───────────────────────────────────────────────────────────

export function getUser(ctx: RouteContext): RouteResponse {
  const user = store.users.get(ctx.params.id);
  if (!user) return notFound(`User "${ctx.params.id}" not found`);
  return ok(user);
}

// ─── PUT /users/:id ───────────────────────────────────────────────────────────

export function updateUser(ctx: RouteContext): RouteResponse {
  const user = store.users.get(ctx.params.id);
  if (!user) return notFound(`User "${ctx.params.id}" not found`);

  const body = ctx.req.body;
  if (!isObject(body)) return badRequest('Request body must be a JSON object');

  const { name, email } = body as UpdateUserBody;

  if (name !== undefined && !isNonEmptyString(name)) {
    return badRequest('Field "name" must be a non-empty string');
  }
  if (email !== undefined && !isNonEmptyString(email)) {
    return badRequest('Field "email" must be a non-empty string');
  }

  // Enforce unique email if changing it
  if (email && email !== user.email) {
    for (const u of store.users.values()) {
      if (u.email === email) return conflict(`A user with email "${email}" already exists`);
    }
  }

  const updated = {
    ...user,
    ...(name ? { name: name.trim() } : {}),
    ...(email ? { email: email.trim() } : {}),
    updatedAt: store.now(),
  };

  store.users.set(user.id, updated);
  return ok(updated);
}

// ─── DELETE /users/:id ────────────────────────────────────────────────────────

export function deleteUser(ctx: RouteContext): RouteResponse {
  if (!store.users.has(ctx.params.id)) return notFound(`User "${ctx.params.id}" not found`);
  store.users.delete(ctx.params.id);
  return noContent();
}

import * as store from '../store.js';
import {
  ok, created, noContent,
  badRequest, notFound, conflict,
  isNonEmptyString, isObject,
} from '../helpers.js';
import type {
  RouteContext, RouteResponse,
  CreateProjectBody, UpdateProjectBody, AddMemberBody,
} from '../types.js';

// ─── GET /projects ────────────────────────────────────────────────────────────

export function listProjects(_ctx: RouteContext): RouteResponse {
  return ok(Array.from(store.projects.values()));
}

// ─── POST /projects ───────────────────────────────────────────────────────────

export function createProject(ctx: RouteContext): RouteResponse {
  const body = ctx.req.body;
  if (!isObject(body)) return badRequest('Request body must be a JSON object');

  const { name, description } = body as CreateProjectBody;
  if (!isNonEmptyString(name)) return badRequest('Field "name" is required and must be a non-empty string');

  const project = {
    id: store.newId(),
    name: name.trim(),
    description: typeof description === 'string' ? description.trim() : '',
    memberIds: [] as string[],
    createdAt: store.now(),
    updatedAt: store.now(),
  };

  store.projects.set(project.id, project);
  return created(project);
}

// ─── GET /projects/:id ───────────────────────────────────────────────────────

export function getProject(ctx: RouteContext): RouteResponse {
  const project = store.projects.get(ctx.params.id);
  if (!project) return notFound(`Project "${ctx.params.id}" not found`);
  return ok(project);
}

// ─── PUT /projects/:id ───────────────────────────────────────────────────────

export function updateProject(ctx: RouteContext): RouteResponse {
  const project = store.projects.get(ctx.params.id);
  if (!project) return notFound(`Project "${ctx.params.id}" not found`);

  const body = ctx.req.body;
  if (!isObject(body)) return badRequest('Request body must be a JSON object');

  const { name, description } = body as UpdateProjectBody;

  if (name !== undefined && !isNonEmptyString(name)) {
    return badRequest('Field "name" must be a non-empty string');
  }

  const updated = {
    ...project,
    ...(name ? { name: name.trim() } : {}),
    ...(description !== undefined ? { description: description.trim() } : {}),
    updatedAt: store.now(),
  };

  store.projects.set(project.id, updated);
  return ok(updated);
}

// ─── DELETE /projects/:id ────────────────────────────────────────────────────

export function deleteProject(ctx: RouteContext): RouteResponse {
  if (!store.projects.has(ctx.params.id)) return notFound(`Project "${ctx.params.id}" not found`);
  store.projects.delete(ctx.params.id);
  return noContent();
}

// ─── POST /projects/:id/members ──────────────────────────────────────────────

export function addMember(ctx: RouteContext): RouteResponse {
  const project = store.projects.get(ctx.params.id);
  if (!project) return notFound(`Project "${ctx.params.id}" not found`);

  const body = ctx.req.body;
  if (!isObject(body)) return badRequest('Request body must be a JSON object');

  const { userId } = body as AddMemberBody;
  if (!isNonEmptyString(userId)) return badRequest('Field "userId" is required and must be a non-empty string');

  if (!store.users.has(userId)) return notFound(`User "${userId}" not found`);
  if (project.memberIds.includes(userId)) return conflict(`User "${userId}" is already a member of this project`);

  const updated = { ...project, memberIds: [...project.memberIds, userId], updatedAt: store.now() };
  store.projects.set(project.id, updated);
  return ok(updated);
}

// ─── DELETE /projects/:id/members ────────────────────────────────────────────

export function removeMember(ctx: RouteContext): RouteResponse {
  const project = store.projects.get(ctx.params.id);
  if (!project) return notFound(`Project "${ctx.params.id}" not found`);

  const body = ctx.req.body;
  if (!isObject(body)) return badRequest('Request body must be a JSON object');

  const { userId } = body as AddMemberBody;
  if (!isNonEmptyString(userId)) return badRequest('Field "userId" is required and must be a non-empty string');

  if (!project.memberIds.includes(userId)) return notFound(`User "${userId}" is not a member of this project`);

  const updated = {
    ...project,
    memberIds: project.memberIds.filter(id => id !== userId),
    updatedAt: store.now(),
  };

  store.projects.set(project.id, updated);
  return ok(updated);
}

import * as store from '../store.js';
import {
  ok, created, noContent,
  badRequest, notFound, unprocessable,
  isNonEmptyString, isObject,
} from '../helpers.js';
import type {
  RouteContext, RouteResponse,
  CreateTaskBody, UpdateTaskBody, UpdateTaskStatusBody, AssignTaskBody,
  TaskStatus,
} from '../types.js';
import { VALID_TRANSITIONS } from '../types.js';

// ─── GET /tasks ───────────────────────────────────────────────────────────────

export function listTasks(ctx: RouteContext): RouteResponse {
  let all = Array.from(store.tasks.values());

  // Optional filter: ?projectId=...
  const { projectId } = ctx.req.query;
  if (projectId) {
    all = all.filter(t => t.projectId === projectId);
  }

  return ok(all);
}

// ─── POST /tasks ──────────────────────────────────────────────────────────────

export function createTask(ctx: RouteContext): RouteResponse {
  const body = ctx.req.body;
  if (!isObject(body)) return badRequest('Request body must be a JSON object');

  const { title, description, projectId, assigneeId } = body as CreateTaskBody;

  if (!isNonEmptyString(title)) return badRequest('Field "title" is required and must be a non-empty string');
  if (!isNonEmptyString(projectId)) return badRequest('Field "projectId" is required and must be a non-empty string');

  if (!store.projects.has(projectId)) return notFound(`Project "${projectId}" not found`);

  if (assigneeId !== undefined && assigneeId !== null) {
    if (!isNonEmptyString(assigneeId)) return badRequest('Field "assigneeId" must be a non-empty string or null');
    if (!store.users.has(assigneeId)) return notFound(`User "${assigneeId}" not found`);
  }

  const task = {
    id: store.newId(),
    title: title.trim(),
    description: typeof description === 'string' ? description.trim() : '',
    status: 'todo' as TaskStatus,
    projectId,
    assigneeId: assigneeId ?? null,
    createdAt: store.now(),
    updatedAt: store.now(),
  };

  store.tasks.set(task.id, task);

  // Notify assignee if set at creation
  if (task.assigneeId) {
    store.createNotification(
      task.assigneeId,
      `You have been assigned to task "${task.title}"`,
    );
  }

  return created(task);
}

// ─── GET /tasks/:id ───────────────────────────────────────────────────────────

export function getTask(ctx: RouteContext): RouteResponse {
  const task = store.tasks.get(ctx.params.id);
  if (!task) return notFound(`Task "${ctx.params.id}" not found`);
  return ok(task);
}

// ─── PUT /tasks/:id ───────────────────────────────────────────────────────────

export function updateTask(ctx: RouteContext): RouteResponse {
  const task = store.tasks.get(ctx.params.id);
  if (!task) return notFound(`Task "${ctx.params.id}" not found`);

  const body = ctx.req.body;
  if (!isObject(body)) return badRequest('Request body must be a JSON object');

  const { title, description } = body as UpdateTaskBody;

  if (title !== undefined && !isNonEmptyString(title)) {
    return badRequest('Field "title" must be a non-empty string');
  }

  const updated = {
    ...task,
    ...(title ? { title: title.trim() } : {}),
    ...(description !== undefined ? { description: description.trim() } : {}),
    updatedAt: store.now(),
  };

  store.tasks.set(task.id, updated);
  return ok(updated);
}

// ─── DELETE /tasks/:id ────────────────────────────────────────────────────────

export function deleteTask(ctx: RouteContext): RouteResponse {
  if (!store.tasks.has(ctx.params.id)) return notFound(`Task "${ctx.params.id}" not found`);
  store.tasks.delete(ctx.params.id);
  return noContent();
}

// ─── PUT /tasks/:id/status ───────────────────────────────────────────────────

export function updateTaskStatus(ctx: RouteContext): RouteResponse {
  const task = store.tasks.get(ctx.params.id);
  if (!task) return notFound(`Task "${ctx.params.id}" not found`);

  const body = ctx.req.body;
  if (!isObject(body)) return badRequest('Request body must be a JSON object');

  const { status } = body as UpdateTaskStatusBody;

  const validStatuses: TaskStatus[] = ['todo', 'in-progress', 'done'];
  if (!validStatuses.includes(status)) {
    return badRequest(`Field "status" must be one of: ${validStatuses.join(', ')}`);
  }

  const allowedNext = VALID_TRANSITIONS[task.status];
  if (!allowedNext.includes(status)) {
    return unprocessable(
      `Cannot transition task from "${task.status}" to "${status}". ` +
      `Allowed transitions: ${allowedNext.length > 0 ? allowedNext.join(', ') : 'none (terminal state)'}`,
    );
  }

  const updated = { ...task, status, updatedAt: store.now() };
  store.tasks.set(task.id, updated);

  // Notify assignee about status change
  if (task.assigneeId) {
    store.createNotification(
      task.assigneeId,
      `Task "${task.title}" status changed from "${task.status}" to "${status}"`,
    );
  }

  return ok(updated);
}

// ─── PUT /tasks/:id/assign ───────────────────────────────────────────────────

export function assignTask(ctx: RouteContext): RouteResponse {
  const task = store.tasks.get(ctx.params.id);
  if (!task) return notFound(`Task "${ctx.params.id}" not found`);

  const body = ctx.req.body;
  if (!isObject(body)) return badRequest('Request body must be a JSON object');

  const { assigneeId } = body as AssignTaskBody;

  if (assigneeId !== null && assigneeId !== undefined) {
    if (!isNonEmptyString(assigneeId)) return badRequest('Field "assigneeId" must be a non-empty string or null');
    if (!store.users.has(assigneeId)) return notFound(`User "${assigneeId}" not found`);
  }

  const resolvedAssigneeId = assigneeId ?? null;
  const updated = { ...task, assigneeId: resolvedAssigneeId, updatedAt: store.now() };
  store.tasks.set(task.id, updated);

  // Notify the new assignee
  if (resolvedAssigneeId) {
    store.createNotification(
      resolvedAssigneeId,
      `You have been assigned to task "${task.title}"`,
    );
  }

  return ok(updated);
}

import * as store from '../store.js';
import {
  ok, created, noContent,
  badRequest, notFound,
  isNonEmptyString, isObject,
} from '../helpers.js';
import type { RouteContext, RouteResponse, CreateCommentBody } from '../types.js';

// ─── GET /comments ────────────────────────────────────────────────────────────

export function listComments(ctx: RouteContext): RouteResponse {
  let all = Array.from(store.comments.values());

  // Optional filter: ?taskId=...
  const { taskId } = ctx.req.query;
  if (taskId) {
    all = all.filter(c => c.taskId === taskId);
  }

  return ok(all);
}

// ─── POST /comments ───────────────────────────────────────────────────────────

export function createComment(ctx: RouteContext): RouteResponse {
  const body = ctx.req.body;
  if (!isObject(body)) return badRequest('Request body must be a JSON object');

  const { taskId, authorId, body: text } = body as CreateCommentBody;

  if (!isNonEmptyString(taskId)) return badRequest('Field "taskId" is required and must be a non-empty string');
  if (!isNonEmptyString(authorId)) return badRequest('Field "authorId" is required and must be a non-empty string');
  if (!isNonEmptyString(text)) return badRequest('Field "body" is required and must be a non-empty string');

  const task = store.tasks.get(taskId);
  if (!task) return notFound(`Task "${taskId}" not found`);

  if (!store.users.has(authorId)) return notFound(`User "${authorId}" not found`);

  const comment = {
    id: store.newId(),
    taskId,
    authorId,
    body: text.trim(),
    createdAt: store.now(),
  };

  store.comments.set(comment.id, comment);

  // Notify task assignee (if any, and if they are not the comment author)
  if (task.assigneeId && task.assigneeId !== authorId) {
    const author = store.users.get(authorId);
    const authorName = author ? author.name : authorId;
    store.createNotification(
      task.assigneeId,
      `${authorName} commented on task "${task.title}": "${text.trim().slice(0, 60)}${text.length > 60 ? '…' : ''}"`,
    );
  }

  // Also notify all project members who are not the author or assignee
  const project = store.projects.get(task.projectId);
  if (project) {
    const alreadyNotified = new Set<string>([authorId, task.assigneeId ?? '']);
    for (const memberId of project.memberIds) {
      if (!alreadyNotified.has(memberId) && store.users.has(memberId)) {
        const author = store.users.get(authorId);
        const authorName = author ? author.name : authorId;
        store.createNotification(
          memberId,
          `${authorName} commented on task "${task.title}" in project "${project.name}"`,
        );
        alreadyNotified.add(memberId);
      }
    }
  }

  return created(comment);
}

// ─── GET /comments/:id ───────────────────────────────────────────────────────

export function getComment(ctx: RouteContext): RouteResponse {
  const comment = store.comments.get(ctx.params.id);
  if (!comment) return notFound(`Comment "${ctx.params.id}" not found`);
  return ok(comment);
}

// ─── DELETE /comments/:id ────────────────────────────────────────────────────

export function deleteComment(ctx: RouteContext): RouteResponse {
  if (!store.comments.has(ctx.params.id)) return notFound(`Comment "${ctx.params.id}" not found`);
  store.comments.delete(ctx.params.id);
  return noContent();
}

import * as store from '../store.js';
import { ok, notFound } from '../helpers.js';
import type { RouteContext, RouteResponse } from '../types.js';

// ─── GET /notifications ──────────────────────────────────────────────────────

export function listNotifications(ctx: RouteContext): RouteResponse {
  let all = Array.from(store.notifications.values());

  // Optional filter: ?userId=...
  const { userId } = ctx.req.query;
  if (userId) {
    all = all.filter(n => n.userId === userId);
  }

  return ok(all);
}

// ─── PUT /notifications/:id/read ─────────────────────────────────────────────

export function markNotificationRead(ctx: RouteContext): RouteResponse {
  const notification = store.notifications.get(ctx.params.id);
  if (!notification) return notFound(`Notification "${ctx.params.id}" not found`);

  const updated = { ...notification, read: true };
  store.notifications.set(notification.id, updated);
  return ok(updated);
}

import type { RouteHandler, RouteResponse, ParsedRequest } from './types.js';
import { methodNotAllowed, notFound } from './helpers.js';

// ─── Users ────────────────────────────────────────────────────────────────────
import {
  listUsers, createUser,
  getUser, updateUser, deleteUser,
} from './handlers/users.js';

// ─── Projects ─────────────────────────────────────────────────────────────────
import {
  listProjects, createProject,
  getProject, updateProject, deleteProject,
  addMember, removeMember,
} from './handlers/projects.js';

// ─── Tasks ────────────────────────────────────────────────────────────────────
import {
  listTasks, createTask,
  getTask, updateTask, deleteTask,
  updateTaskStatus, assignTask,
} from './handlers/tasks.js';

// ─── Comments ─────────────────────────────────────────────────────────────────
import {
  listComments, createComment,
  getComment, deleteComment,
} from './handlers/comments.js';

// ─── Notifications ────────────────────────────────────────────────────────────
import {
  listNotifications, markNotificationRead,
} from './handlers/notifications.js';

// ─── Route Table Entry ────────────────────────────────────────────────────────

interface Route {
  method: string;        // 'GET' | 'POST' | 'PUT' | 'DELETE' | '*'
  pattern: string[];     // e.g. ['users', ':id'] — ':param' means dynamic segment
  handler: RouteHandler;
}

// ─── Route Definitions ────────────────────────────────────────────────────────

const routes: Route[] = [
  // Users
  { method: 'GET',    pattern: ['users'],                    handler: listUsers },
  { method: 'POST',   pattern: ['users'],                    handler: createUser },
  { method: 'GET',    pattern: ['users', ':id'],             handler: getUser },
  { method: 'PUT',    pattern: ['users', ':id'],             handler: updateUser },
  { method: 'DELETE', pattern: ['users', ':id'],             handler: deleteUser },

  // Projects
  { method: 'GET',    pattern: ['projects'],                 handler: listProjects },
  { method: 'POST',   pattern: ['projects'],                 handler: createProject },
  { method: 'GET',    pattern: ['projects', ':id'],          handler: getProject },
  { method: 'PUT',    pattern: ['projects', ':id'],          handler: updateProject },
  { method: 'DELETE', pattern: ['projects', ':id'],          handler: deleteProject },
  { method: 'POST',   pattern: ['projects', ':id', 'members'], handler: addMember },
  { method: 'DELETE', pattern: ['projects', ':id', 'members'], handler: removeMember },

  // Tasks
  { method: 'GET',    pattern: ['tasks'],                    handler: listTasks },
  { method: 'POST',   pattern: ['tasks'],                    handler: createTask },
  { method: 'GET',    pattern: ['tasks', ':id'],             handler: getTask },
  { method: 'PUT',    pattern: ['tasks', ':id'],             handler: updateTask },
  { method: 'DELETE', pattern: ['tasks', ':id'],             handler: deleteTask },
  { method: 'PUT',    pattern: ['tasks', ':id', 'status'],   handler: updateTaskStatus },
  { method: 'PUT',    pattern: ['tasks', ':id', 'assign'],   handler: assignTask },

  // Comments
  { method: 'GET',    pattern: ['comments'],                 handler: listComments },
  { method: 'POST',   pattern: ['comments'],                 handler: createComment },
  { method: 'GET',    pattern: ['comments', ':id'],          handler: getComment },
  { method: 'DELETE', pattern: ['comments', ':id'],          handler: deleteComment },

  // Notifications
  { method: 'GET',    pattern: ['notifications'],            handler: listNotifications },
  { method: 'PUT',    pattern: ['notifications', ':id', 'read'], handler: markNotificationRead },
];

// ─── Matching Logic ───────────────────────────────────────────────────────────

function matchPattern(
  pattern: string[],
  segments: string[],
): Record<string, string> | null {
  if (pattern.length !== segments.length) return null;

  const params: Record<string, string> = {};
  for (let i = 0; i < pattern.length; i++) {
    if (pattern[i].startsWith(':')) {
      params[pattern[i].slice(1)] = segments[i];
    } else if (pattern[i] !== segments[i]) {
      return null;
    }
  }
  return params;
}

// ─── Dispatch ────────────────────────────────────────────────────────────────

export async function dispatch(req: ParsedRequest): Promise<RouteResponse> {
  const segments = req.segments;
  const method = req.method.toUpperCase();

  let pathMatched = false;

  for (const route of routes) {
    const params = matchPattern(route.pattern, segments);
    if (params === null) continue;

    pathMatched = true;

    if (route.method !== method) continue;

    return await route.handler({ req, params });
  }

  if (pathMatched) return methodNotAllowed();
  return notFound('Route not found');
}

import http from 'http';
import { URL } from 'url';
import { dispatch } from './router.js';
import type { ParsedRequest } from './types.js';

// ─── Body Parser ─────────────────────────────────────────────────────────────

function readBody(req: http.IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on('data', (chunk: Buffer) => chunks.push(chunk));
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function parseBody(raw: string): unknown {
  if (!raw.trim()) return null;
  try {
    return JSON.parse(raw);
  } catch {
    return undefined; // signals a parse error
  }
}

// ─── URL Parser ──────────────────────────────────────────────────────────────

function parseQuery(search: string): Record<string, string> {
  const params = new URLSearchParams(search);
  const result: Record<string, string> = {};
  for (const [key, value] of params.entries()) {
    result[key] = value;
  }
  return result;
}

// ─── Server Factory ──────────────────────────────────────────────────────────

export function createServer(): http.Server {
  return http.createServer(async (req, res) => {
    const method = req.method ?? 'GET';
    const rawUrl = req.url ?? '/';

    // Parse the URL — use a dummy base since we only care about path + query
    const parsed = new URL(rawUrl, 'http://localhost');
    const pathname = parsed.pathname.replace(/\/+$/, '') || '/'; // strip trailing slash
    // Build segments, drop leading empty string from split
    const segments = pathname.split('/').filter(s => s.length > 0);
    const query = parseQuery(parsed.search);

    // Read & parse request body
    const rawBody = await readBody(req).catch(() => '');
    const body = parseBody(rawBody);

    // If body is undefined it means JSON was malformed
    if (body === undefined) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Invalid JSON in request body' }));
      return;
    }

    const parsedReq: ParsedRequest = { method, pathname, segments, query, body };

    let response;
    try {
      response = await dispatch(parsedReq);
    } catch (err) {
      console.error('[Server Error]', err);
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Internal server error' }));
      return;
    }

    const { status, body: responseBody } = response;

    if (status === 204) {
      res.writeHead(204);
      res.end();
      return;
    }

    res.writeHead(status, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(responseBody, null, 2));
  });
}

